def apply(inputs, premises):
    answer = {}
    n = len(inputs["asset_descriptions"])
    for i in range(n):
        description = inputs["asset_descriptions"][i]
        value = float(inputs["asset_values"][i])
        claims = []
        if inputs["governing_regime"] == "Illinois":
            if bool(inputs["asset_is_personal_nonbusiness_property"][i]):
                if inputs["output_family"] == "EV":
                    claims = [{"citation": premises["illinois_other_property_citation"], "claim_value": min(value, float(premises["illinois_other_property_limit"]))}]
                else:
                    claims = [premises["illinois_other_property_citation"]]
        elif inputs["governing_regime"] == "Federal and Wisconsin":
            if bool(inputs["asset_is_federal_household_category"][i]):
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["federal_household_citation"], "claim_value": min(value, float(premises["federal_household_item_limit"]))}]
                else:
                    claims = claims + [premises["federal_household_citation"]]
            if bool(inputs["asset_is_personal_tangible_property"][i]):
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["federal_wildcard_citation"], "claim_value": min(value, float(premises["federal_wildcard_base_limit"]))}]
                    claims = claims + [{"citation": premises["wisconsin_consumer_goods_citation"], "claim_value": min(value, float(premises["wisconsin_consumer_goods_limit"]))}]
                else:
                    claims = claims + [premises["federal_wildcard_citation"], premises["wisconsin_consumer_goods_citation"]]
        elif inputs["governing_regime"] == "Federal and Pennsylvania":
            if bool(inputs["asset_is_personal_tangible_property"][i]):
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["federal_household_citation"], "claim_value": min(value, float(premises["federal_household_item_limit"]))}]
                    wildcard_limit = float(premises["federal_wildcard_base_limit"]) * int(inputs["number_of_debtors"])
                    claims = claims + [{"citation": premises["federal_wildcard_citation"], "claim_value": min(value, wildcard_limit)}]
                else:
                    claims = claims + [premises["federal_household_citation"], premises["federal_wildcard_citation"]]
            if bool(inputs["asset_is_personal_nonbusiness_property"][i]):
                if inputs["output_family"] == "EV":
                    pennsylvania_limit = float(premises["pennsylvania_general_property_limit"]) * int(inputs["number_of_debtors"])
                    claims = claims + [{"citation": premises["pennsylvania_general_property_citation"], "claim_value": min(value, pennsylvania_limit)}]
                else:
                    claims = claims + [premises["pennsylvania_general_property_citation"]]
            if bool(inputs["asset_is_wearing_apparel"][i]):
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["pennsylvania_wearing_apparel_citation"], "claim_value": value}]
                else:
                    claims = claims + [premises["pennsylvania_wearing_apparel_citation"]]
        elif inputs["governing_regime"] == "Arizona" or inputs["governing_regime"] == "Federal and Arizona":
            if bool(inputs["asset_is_arizona_wearing_apparel"][i]):
                apparel_limit = float(premises["arizona_wearing_apparel_limit"]) * int(inputs["number_of_debtors"])
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["arizona_wearing_apparel_citation"], "claim_value": min(value, apparel_limit)}]
                else:
                    claims = claims + [premises["arizona_wearing_apparel_citation"]]
            if bool(inputs["asset_is_arizona_household_good_or_appliance"][i]):
                household_limit = float(premises["arizona_household_limit"]) * int(inputs["number_of_debtors"])
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["arizona_household_citation"], "claim_value": min(value, household_limit)}]
                else:
                    claims = claims + [premises["arizona_household_citation"]]
        answer[description] = claims
    return {"answer": answer}
